/**
 * Sunfizz flavour palette. Colours match the packshots generated by
 * catalog/tools/generate-catalog.mjs. Products are matched by their Shopify
 * tag (orange / grapefruit / lemon / lime / variety), so a renamed product
 * keeps its colours as long as the tag stays.
 */
export type FlavourKey = 'orange' | 'grapefruit' | 'lemon' | 'lime' | 'variety';

export type Ingredient = {
  name: string;
  kind: 'citrus' | 'flower' | 'leaf' | 'botanical';
};

export type Flavour = {
  key: FlavourKey;
  /** Short name for swatches. */
  label: string;
  /** Tasting notes, e.g. "Orange, tangerine & ginger". */
  notes: string;
  ingredients: Ingredient[];
  /** Can body gradient: edge, mid, highlight, far edge. */
  body: [string, string, string, string];
  /** Accent text/ink on cream (AA for large text). */
  accent: string;
  peel: string;
  flesh: string;
  /** Text printed on the coloured part of the can. */
  bodyText: string;
  /** Page tints behind the product. */
  bg: string;
  bgLight: string;
  /** Printed on the can's flavour pill. */
  canLabel: string;
};

