export const FLAVOUR_ORDER = ['orange', 'grapefruit', 'lemon', 'lime'] as const;

/** The mixed pack borrows its cans from the four flavours. */
export const VARIETY = {
  key: 'variety' as const,
  label: 'Variety Pack',
  notes: 'All four flavours in one box',
  ingredients: FLAVOUR_ORDER.map((k) => ({
    name: FLAVOURS[k].label,
    kind: 'citrus' as const,
  })),
  accent: '#c2410c',
  bg: '#ffe7b8',
  bgLight: '#fff8ea',
};

export type FlavourLike = Flavour | typeof VARIETY;

export function flavourKeyFromTags(tags: readonly string[] | undefined): FlavourKey | null {
  if (!tags) return null;
  const lower = tags.map((t) => t.toLowerCase());
  if (lower.includes('variety')) return 'variety';
  return FLAVOUR_ORDER.find((k) => lower.includes(k)) ?? null;
}

export function flavourFor(tags: readonly string[] | undefined): FlavourLike | null {
  const key = flavourKeyFromTags(tags);
  if (!key) return null;
  return key === 'variety' ? VARIETY : FLAVOURS[key];
}

/** Sort products into the house order: the four flavours, then the variety pack, then anything else. */
export function byFlavourOrder<T extends {tags: readonly string[]}>(products: readonly T[]): T[] {
  const rank = (p: T) => {
    const key = flavourKeyFromTags(p.tags);
    if (key === 'variety') return FLAVOUR_ORDER.length;
    return key ? FLAVOUR_ORDER.indexOf(key) : FLAVOUR_ORDER.length + 1;
  };
  return [...products].sort((a, b) => rank(a) - rank(b));
}

/** CSS custom properties that tint a product's surroundings. */
export function flavourStyle(flavour: FlavourLike | null): React.CSSProperties {
  if (!flavour) return {};
  return {
    '--f-bg': flavour.bg,
    '--f-bg-light': flavour.bgLight,
    '--f-accent': flavour.accent,
    '--f-swatch':
      flavour.key === 'variety'
        ? `conic-gradient(${FLAVOUR_ORDER.map((k, i) => `${FLAVOURS[k].body[1]} ${i * 25}% ${(i + 1) * 25}%`).join(', ')})`
        : flavour.body[1],
  } as React.CSSProperties;
}
